  'Gini coefficient': ['基尼系数', '收入分配', '贫富差距', 'gini']
};

/**
 * 高亮文本中的关键词
 */
export function highlightText(content, fieldKey) {
  if (!content || !fieldKey) return content;
  const keywords = FIELD_KEYWORDS[fieldKey];
  if (!keywords || !keywords.length) return content;
  let highlightedContent = content;
  keywords.forEach(keyword => {
    if (keyword.trim()) {
      const regex = new RegExp(`(${escapeRegExp(keyword)})`, 'gi');
      highlightedContent = highlightedContent.replace(regex, '<mark class="text-highlight">$1</mark>');
    }
  });
  return highlightedContent;
}

