 */
export function clearHighlights() {
  const highlights = document.querySelectorAll('.text-highlight');
  highlights.forEach(highlight => {
    const parent = highlight.parentNode;
    parent.replaceChild(document.createTextNode(highlight.textContent), highlight);
    parent.normalize();
  });
}

/**
 * 转义正则表达式特殊字符
 */
function escapeRegExp(string) {
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * 在指定元素中高亮文本
 */
export function highlightElementText(element, fieldKey) {
  if (!element || !fieldKey) return;
  const keywords = FIELD_KEYWORDS[fieldKey];
  if (!keywords || !keywords.length) return;

  // 先清除现有高亮
  clearHighlights();

  // 遍历文本节点
  walkTextNodes(element, textNode => {
    const content = textNode.textContent;
    let hasMatch = false;
    let newContent = content;
    keywords.forEach(keyword => {
      if (keyword && content.toLowerCase().includes(keyword.toLowerCase())) {
        const regex = new RegExp(`(${escapeRegExp(keyword)})`, 'gi');
        newContent = newContent.replace(regex, '<mark class="text-highlight">$1</mark>');
        hasMatch = true;
      }
    });
    if (hasMatch) {
      const newElement = document.createElement('span');
      newElement.innerHTML = newContent;
      textNode.parentNode.replaceChild(newElement, textNode);
    }
  });
}

/**
 * 遍历所有文本节点
 */
function walkTextNodes(element, callback) {
  const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT, null, false);
  let textNode;
  const textNodes = [];
  while (textNode = walker.nextNode()) {
    textNodes.push(textNode);
  }
  textNodes.forEach(callback);
}

/**
 * 滚动到第一个高亮元素
 */
export function scrollToFirstHighlight() {
  const firstHighlight = document.querySelector('.text-highlight');
  if (firstHighlight) {
    firstHighlight.scrollIntoView({
      behavior: 'smooth',
      block: 'center',
      inline: 'nearest'
    });
  }
}

/**
 * 在多个元素中高亮文本
 */
export function highlightMultipleElements(elements, fieldKey) {
  if (!elements || !fieldKey) return;
  elements.forEach(element => {
    if (element) {
      highlightElementText(element, fieldKey);
    }
  });
}

